 WHERE NOT EXISTS (SELECT 1 FROM essentials.governments g WHERE g.id = '95af0460-6acd-56ba-a04b-82fe98574eba'::uuid);
INSERT INTO essentials.chambers (id, government_id, name, name_formal, term_length, website_url, policy_engagement_level)
SELECT 'bb1001bd-c56b-55ba-adc9-0b9f4c78a404'::uuid, '95af0460-6acd-56ba-a04b-82fe98574eba'::uuid, 'School Board', 'School Board of Escambia County', '4 years', 'https://www.escambiaschools.org/district-leadership/school-board', 'full'
 WHERE NOT EXISTS (SELECT 1 FROM essentials.chambers c WHERE c.id = 'bb1001bd-c56b-55ba-adc9-0b9f4c78a404'::uuid);
