-- ═══ Post-verify gate ═══
DO $$
DECLARE n int; n2 int; bad text;
BEGIN
  -- 1. one valid G5420 polygon per board (8 new + Chino Valley's existing 0608460)
  SELECT count(*) INTO n FROM (VALUES ('fb97ba82-a975-58d5-b9f0-94440a2c3506'::uuid, '1200510', 5), ('d57cceb6-0823-5a94-9049-4c55aba44d69'::uuid, '1200300', 5), ('ccba59b0-fb43-5590-8fc1-6ddccbcbf46b'::uuid, '4825170', 7), ('9f375c49-04b0-528f-8a5a-e9496b80e8b8'::uuid, '4825260', 7), ('57f62331-7bd1-5f6a-8c5d-e5c965cbc05a'::uuid, '2400570', 5), ('2ea18e2d-1d8d-5853-9e46-9c910c9708f4'::uuid, '5102250', 9), ('dd3c4dfe-9042-526f-b920-35feb312844d'::uuid, '5103840', 11), ('b93d7425-b909-5bda-b548-cdd4ae1942c4'::uuid, '2706090', 6), ('dd9a892f-b1b9-5ad4-8643-7d380e567220'::uuid, '0608460', 5)) v(did, geo, seats)
    JOIN essentials.geofence_boundaries gb ON gb.geo_id = v.geo AND gb.mtfcc = 'G5420'
   WHERE public.ST_IsValid(gb.geometry) AND NOT public.ST_IsEmpty(gb.geometry) AND public.ST_SRID(gb.geometry) = 4326;
  IF n <> 9 THEN RAISE EXCEPTION 'expected 9 valid G5420 polygons, got %', n; END IF;

  -- 2. nine SCHOOL districts, each with its seat count of offices; 60 offices in all
  SELECT count(*) INTO n FROM (VALUES ('fb97ba82-a975-58d5-b9f0-94440a2c3506'::uuid, '1200510', 5), ('d57cceb6-0823-5a94-9049-4c55aba44d69'::uuid, '1200300', 5), ('ccba59b0-fb43-5590-8fc1-6ddccbcbf46b'::uuid, '4825170', 7), ('9f375c49-04b0-528f-8a5a-e9496b80e8b8'::uuid, '4825260', 7), ('57f62331-7bd1-5f6a-8c5d-e5c965cbc05a'::uuid, '2400570', 5), ('2ea18e2d-1d8d-5853-9e46-9c910c9708f4'::uuid, '5102250', 9), ('dd3c4dfe-9042-526f-b920-35feb312844d'::uuid, '5103840', 11), ('b93d7425-b909-5bda-b548-cdd4ae1942c4'::uuid, '2706090', 6), ('dd9a892f-b1b9-5ad4-8643-7d380e567220'::uuid, '0608460', 5)) v(did, geo, seats)
    JOIN essentials.districts d ON d.id = v.did AND d.district_type = 'SCHOOL' AND d.mtfcc = 'G5420' AND d.geo_id = v.geo
   WHERE (SELECT count(*) FROM essentials.offices o WHERE o.district_id = d.id) = v.seats;
  IF n <> 9 THEN RAISE EXCEPTION 'expected 9 SCHOOL districts with their seat counts, got %', n; END IF;
