  SELECT count(*) INTO n FROM (VALUES ('0a0b256b-9b89-5839-b70c-a598cc9f879c'::uuid, '1e2d6569-3bff-5e81-b7be-e362e2fd7012'::uuid), ('9b6a99a1-0d97-5131-a2c1-532f352a8c92'::uuid, '1989c671-5762-5ecc-bdc5-f7ffc866fa86'::uuid), ('11a03014-ca5d-5516-a6e8-942e42494f09'::uuid, '02ff3b3f-11e6-5b11-a0a0-f142a381522d'::uuid), ('00ed81b2-163f-5f18-9208-80f51e38861e'::uuid, 'a510247c-f50f-5a6f-8fd7-fa5c6bdb9d38'::uuid), ('ad12c59f-146e-5b5e-a6d3-d9903e1210c9'::uuid, '1d211d48-18bd-5691-a9fe-de211be1e44d'::uuid), ('423054a8-9447-5c3c-a6a2-73f6d6ec9e36'::uuid, '06efded0-0b18-5fd9-a357-b973df8cd372'::uuid), ('a5721fe7-8e76-5d02-8864-971cc5085750'::uuid, 'e355e59f-b6b9-5eae-a701-6d4f7f622499'::uuid), ('c303ae72-426d-56cf-b10b-fdefb2dbb447'::uuid, '860fd6b9-87fb-5dda-8471-065e3a5957f2'::uuid), ('ec048c1c-9fbf-503e-9a27-0d9cfd6b77d9'::uuid, 'c8a7d3e1-59bb-569d-bdbf-7e1a0f53e1ad'::uuid), ('b1b7df02-c4c5-5dd3-ad4e-b85517f383d5'::uuid, '9fb0b1b2-1c29-55cc-94e8-ab918eca2618'::uuid), ('57e5e1c7-c67a-5474-addc-b798142c8012'::uuid, 'daa327ee-a69d-5e87-ad58-89ad7327780f'::uuid), ('27bb5bca-4ae2-5f1c-944a-d80b4db64777'::uuid, 'ff597603-de64-5469-86ce-49c2cecf632f'::uuid), ('b3b5e19d-f1a3-52a6-8d6a-2d178843756f'::uuid, '786021f2-b016-5e1a-a1bb-2dfe1e7b138c'::uuid), ('898556f9-af06-512b-9ef5-9ffbe52e906a'::uuid, 'e038ab5a-6f9b-5be9-957e-0635c7c761ed'::uuid), ('84cbd231-e4af-5422-951d-9926a7a51397'::uuid, '26dcd6b0-dc3a-55e5-a360-7bc26a56ce67'::uuid), ('374ca82a-f202-5057-9281-81271ae41def'::uuid, 'a8b06d8c-4d27-5e22-96dd-d8437360663c'::uuid), ('b5c4e582-7366-58e5-9d26-f1d4435221c4'::uuid, '560b1951-a1c9-5fa2-a990-a42d07c38ee5'::uuid), ('a21fe489-222f-5318-9375-e0e3e90701cb'::uuid, '52e919fb-0075-5abb-8cbe-8be3f0517dc3'::uuid), ('b0c540c8-6ddc-5e7d-88ab-1af00804c1f4'::uuid, 'b2041f17-ad39-54d0-af75-815bd83b32a4'::uuid), ('69344547-946a-5101-8486-acc574151506'::uuid, 'a567bbe2-2c19-5fee-acd4-cafa0212a656'::uuid), ('9972d9e2-86db-54ae-9abf-df3b274d14e1'::uuid, 'de7aa3a7-96f3-5323-add2-a5181bfde7