c-5654-86ad-dd92b7cd026e'::uuid, '43c21625-3268-5580-a750-bcdd22fd6ab5'::uuid), ('0a70ec9d-68e0-5226-adca-40cd9116df75'::uuid, '00e6f571-4d8b-5241-87c3-5898e0ae2e18'::uuid), ('4b70b4b8-1e8b-5787-9185-043fb5517b0f'::uuid, 'bc799057-7962-565a-b924-862385fdd535'::uuid), ('f8851ae2-808a-5ee3-9fad-5a7e0f7f7ab8'::uuid, 'ffe07962-8735-5aa6-ae8c-2a34df0151dd'::uuid), ('68e6f8e4-e22e-5560-a1ef-4f3abdc585c1'::uuid, '3e74e711-c6c1-5e3b-8f47-25f1f0f3fc03'::uuid), ('1f2c96e7-5ade-5aad-8327-3e43bb531b05'::uuid, '718007cb-41cd-5e5e-8b89-fddd6b460ef1'::uuid), ('577bccce-f781-5aa2-b566-6c80d68e2c62'::uuid, '5c0ccd1c-f298-52db-9093-e2ff08ac1249'::uuid), ('647c1d08-6a36-5b3e-ae75-ede46878a19f'::uuid, 'c0e40eac-d305-5d00-a364-afbc306425f5'::uuid), ('73d88c15-7751-5c02-af0c-b29cb89f7a49'::uuid, 'c8c7b9b0-9975-573b-9e69-9a06dde8f2c9'::uuid), ('562235bb-0ceb-5917-9480-fa575795271e'::uuid, '323d5c20-2135-5d88-a441-596ca1f3ee32'::uuid), ('564e565f-2cc5-5f78-8903-993c1efe325b'::uuid, '27e003b0-543c-505d-b375-2e86119a61e3'::uuid), ('92e9346f-b7c2-5371-a910-24dd83b6859b'::uuid, '3009d25f-2116-55ea-91b8-5885df22e289'::uuid), ('7e556155-5d13-572f-876b-f80a1029d982'::uuid, '59160c91-1e45-5522-962a-948920f79145'::uuid), ('fb1fff2e-bfa4-53db-b9bb-ad7132de3fc9'::uuid, '5c6d7649-d5ff-56a6-b197-7e408513725b'::uuid), ('e264fa58-7548-533d-a403-a0ccbdda86b4'::uuid, '5f76110b-eb6c-59b4-8c6a-c97e8722cc05'::uuid), ('aa7fe2be-adc7-5066-a3d2-1f4273a8a35b'::uuid, '443b36be-c877-561b-9128-e8406050297a'::uuid), ('c94da716-3c9d-58a3-90b1-a35cad7ff3c1'::uuid, '643448b9-804f-58d5-9bc8-aa5c3576d3c1'::uuid)) v(oid, pid) JOIN essentials.politicians p ON p.id = v.pid
   WHERE NOT p.is_incumbent OR NOT p.is_active OR p.party IS NOT NULL;
  IF n <> 0 THEN RAISE EXCEPTION '% seated member(s) with a wrong flag or a party', n; END IF;
  SELECT count(*) INTO n FROM essentials.politicians p WHERE p.id IN ('67b77315-5201-5e8a-8028-9f815d7dbb00'::uuid, 'd4b2e507-2ad7-5201-af17-5bac880c7edd'::uuid, '81bcc69c-22a0-5cf2-a23c-3f47110f8697'::uuid, '56142fc3-7253-5ed1-a133-d30408ce455b'::uuid, '2bf55c8f-951a-5f41-88f0-188cd670e9c3'::uuid, 'a3a430dc-8b22-556f-af3a-d41f0194f27c'::uuid, 'b6327ee7-9cb3-595b-82f0-4c2df16dbd95'::uuid, '88746ad5-7573-52c3-bb0f-09330a8d0f6b'::uuid, '23c6a090-8b08-57c9-b0b6-c1a3473c6268'::uuid, '9321e268-73d3-51c2-8028-db253c942522'::uuid, 'e97fc5c1-bf29-5351-8138-1569ba8c030f'::uuid, 'dd72a159-1298-5279-9c27-9cfbff7c1f54'::uuid, 'e678a183-d028-5032-b45f-6b8884ab0273'::uuid, '48d17b22-3339-56b3-bd00-c02805a7ec56'::uuid, '8e42053a-a353-5dae-9a43-f2afc09eb1ec'::uuid, '87beb19c-2530-5a95-a0b1-b298db9ed567'::uuid, '8b54f748-6d78-5315-bc7d-c898237b06d3'::uuid, 'd68a978c-53df-5652-a15b-9bc2a6ebd8ec'::uuid, 'f9038459-0151-5f99-95ed-a704a56caf4d'::uuid, 'e2ebe1e9-1117-5849-8edc-c7a7447d413d'::uuid, '72cd6675-1dd9-53af-a962-1bf935097205'::uuid, '0321c7eb-0c68-54c9-95b4-6f95bcc4d517'::uuid, 'e50ceeee-6c6d-5655-b8f3-7428f86a3b3a'::uuid, 'f65cbe11-70b7-5d8b-9927-819beaa854f8'::uuid, '33e7e69b-f05d-5d57-87f0-7986c0a384ef'::uuid)
   AND (p.is_incumbent OR NOT p.is_active OR p.party IS NOT NULL
        OR EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.politician_id = p.id AND t.term_end IS NULL));
  IF n <> 0 THEN RAISE EXCEPTION '% former member(s) with a wrong flag or an open term', n; END IF;

  -- 6. every record voter held a seat on their board on the record date (NULL start = unknown, open to the past)
  SELECT count(*), string_agg(v.pid::text || '@' || v.d, ', ') FILTER (WHERE t.id IS NULL) INTO n, bad
    FROM (VALUES ('1e2d6569-3bff-5e81-b7be-e362e2fd7012'::uuid, '2023-06-20'::date), ('1989c671-5762-5ecc-bdc5-f7ffc866fa86'::uuid, '2023-06-20'::date), ('02ff3b3f-11e6-5b11-a0a0-f142a381522d'::uuid, '2023-06-20'::date), ('67b77315-5201-5e8a-8028-9f815d7dbb00'::uuid, '2023-06-20'::date), ('d4b2e507-2ad7-5201-af17-5bac880c7edd'::uuid, '2023-06-20'::date), ('a510247c-f50f-5a6f-8fd7-fa5c6bdb9d38'::uuid, '2025-10-21'::date), ('1d211d48-18bd-5691-a9fe-de211be1e44d'::uuid, '2025-10-21'::date), ('9fb0b1b2-1c29-55cc-94e8-ab918eca2618'::uuid, '2023-04-06'::date), ('81bcc69c-22a0-5cf2-a23c-3f47110f8697'::uuid, '2023-04-06'::date), ('860fd6b9-87fb-5dda-8471-065e3a5957f2'::uuid, '2023-04-06'::date), ('c8a7d3e1-59bb-569d-bdbf-7e1a0f53e1ad'::uuid, '2023-04-06'::date), ('06efded0-0b18-5fd9-a357-b973df8cd372'::uuid, '2023-04-06'::date), ('56142fc3-7253-5ed1-a133-d30408ce455b'::uuid, '2024-08-26'::date), ('a3a430dc-8b22-556f-af3a-d41f0194f27c'::uuid, '2024-08-26'::date), ('b6327ee7-9cb3-595b-82f0-4c2df16dbd95'::uuid, '2024-08-26'::date), ('2bf55c8f-951a-5f41-88f0-188cd670e9c3'::uuid, '2024-08-26'::date), ('ff597603-de64-5469-86ce-49c2cecf632f'::uuid, '2024-08-26'::date), ('a8b06d8c-4d27-5e22-96dd-d8437360663c'::uuid, '2024-08-26'::date), ('560b1951-a1c9-5fa2-a990-a42d07c38ee5'::uuid, '2024-08-26'::date), ('88746ad5-7573-52c3-bb0f-09330a8d0f6b'::uuid, '2022-08-22'::date), ('23c6a090-8b08-57c9-b0b6-c1a3473c6268'::uuid, '2022-08-22'::date), ('9321e268-73d3-51c2-8028-db253c942522'::uuid, '2022-08-22'::date), ('e678a183-d028-5032-b45f-6b8884ab0273'::uuid, '2022-08-22'::date), ('e97fc5c1-bf29-5351-8138-1569ba8c030f'::uuid, '2022-08-22'::date), ('48d17b22-3339-56b3-bd00-c02805a7ec56'::uuid, '2022-08-22'::date), ('dd72a159-1298-5279-9c27-9cfbff7c1f54'::uuid, '2022-08-22'::date), ('d9027dfb-57de-5306-9f16-b148c83c9995'::uuid, '2026-08-18'::date), ('34b4e239-05c7-56a5-9570-481b41e5ea1c'::uuid, '2026-08-18'::date), ('78c8d3df-cc06-577b-97bc-d344e269fffd'::uuid, '2026-08-18'::date), ('b9c1070f-0ed7-5084-bc1d-8573a2d92427'::uuid, '2026-08-18'::date), ('5af7293a-6320-5c38-beb5-3f62adc05a5b'::uuid, '2026-08-18'::date), ('8e42053a-a353-5dae-9a43-f2afc09eb1ec'::uuid, '2023-06-27'::date), ('d68a978c-53df-5652-a15b-9bc2a6ebd8ec'::uuid, '2023-06-27'::date), ('87beb19c-2530-5a95-a0b1-b298db9ed567'::uuid, '2023-06-27'::date), ('e2ebe1e9-1117-5849-8edc-c7a7447d413d'::uuid, '2023-06-27'::date), ('f9038459-0151-5f99-95ed-a704a56caf4d'::uuid, '2023-06-27'::date), ('8b54f748-6d78-5315-bc7d-c898237b06d3'::uuid, '2023-06-27'::date), ('bc799057-7962-565a-b924-862385fdd535'::uuid, '2024-02-27'::date), ('853c008a-d5bd-5700-8728-bb8f35b73921'::uuid, '2024-02-27'::date), ('72cd6675-1dd9-53af-a962-1bf935097205'::uuid, '2024-02-27'::date), ('0321c7eb-0c68-54c9-95b4-6f95bcc4d517'::uuid, '2024-02-27'::date), ('c0e40eac-d305-5d00-a364-afbc306425f5'::uuid, '2024-02-12'::date), ('c8c7b9b0-9975-573b-9e69-9a06dde8f2c9'::uuid, '2024-02-12'::date), ('5c0ccd1c-f298-52db-9093-e2ff08ac1249'::uuid, '2024-02-12'::date), ('e50ceeee-6c6d-5655-b8f3-7428f86a3b3a'::uuid, '2024-02-12'::date), ('323d5c20-2135-5d88-a441-596ca1f3ee32'::uuid, '2024-02-12'::date), ('27e003b0-543c-505d-b375-2e86119a61e3'::uuid, '2024-02-12'::date), ('5f76110b-eb6c-59b4-8c6a-c97e8722cc05'::uuid, '2023-11-16'::date), ('643448b9-804f-58d5-9bc8-aa5c3576d3c1'::uuid, '2023-11-16'::date), ('5c6d7649-d5ff-56a6-b197-7e408513725b'::uuid, '2023-11-16'::date), ('f65cbe11-70b7-5d8b-9927-819beaa854f8'::uuid, '2022-09-27'::date), ('33e7e69b-f05d-5d57-87f0-7986c0a384ef'::uuid, '2022-09-27'::date)) v(pid, d)
    LEFT JOIN LATERAL (SELECT t.id FROM essentials.office_terms t JOIN essentials.offices o ON o.id = t.office_id
                         JOIN essentials.districts d ON d.id = o.district_id AND d.district_type = 'SCHOOL'
                        WHERE t.politician_id = v.pid AND daterange(t.term_start, t.term_end, '[]') @> v.d LIMIT 1) t ON true;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'record voter(s) not seated on the record date: %', bad; END IF;
  IF n <> 52 THEN RAISE EXCEPTION 'expected 52 record-voter checks, got %', n; END IF;

  -- 7. Alpine: Hacken and Bonner closed, the day before Peterson / Lincoln start; the board still has 7 holders
  SELECT count(*) INTO n FROM essentials.office_terms a JOIN essentials.office_terms b ON b.office_id = a.office_id AND b.term_start = a.term_end + 1
   WHERE a.politician_id IN ('f65cbe11-70b7-5d8b-9927-819beaa854f8'::uuid, '33e7e69b-f05d-5d57-87f0-7986c0a384ef'::uuid) AND b.term_end IS NULL
     AND b.id IN ('dc9df50a-5b24-48ff-8f37-e48797b16af2'::uuid, '4a66b327-5aa7-4c06-a4a4-4466411e7da3'::uuid);
  IF n <> 2 THEN RAISE EXCEPTION 'Alpine former terms not chained to their successors (% of 2)', n; END IF;
  SELECT count(*) INTO n FROM essentials.offices o JOIN essentials.office_current_holder och ON och.office_id = o.id AND och.politician_id IS NOT NULL
   WHERE o.district_id = '070c3de3-609e-49e9-98dd-d555403a9bde'::uuid;
  IF n <> 7 THEN RAISE EXCEPTION 'Alpine should still have 7 holders, got %', n; END IF;

  -- 8. END TO END: an interior point of each polygon resolves, through the address guard (G54xx -> SCHOOL),
  --    to every current holder on that board (Keller: 6 of 7, Place 6 vacant)
  SELECT count(*) INTO n FROM (
    SELECT v.seats - CASE WHEN v.geo = '4825260' THEN 1 ELSE 0 END AS want,
           (SELECT count(DISTINCT och.politician_id)
              FROM essentials.geofence_boundaries gb
              JOIN essentials.districts d ON d.geo_id = gb.geo_id AND d.district_type = 'SCHOOL'
                   AND gb.mtfcc IN ('G5400','G5410','G5420')
              JOIN essentials.offices o ON o.district_id = d.id
              JOIN essentials.office_current_holder och ON och.office_id = o.id AND och.politician_id IS NOT NULL
              JOIN essentials.politicians p ON p.id = och.politician_id AND p.is_active AND p.is_incumbent
             WHERE d.id = v.did AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(g.geometry))) AS got
      FROM (VALUES ('fb97ba82-a975-58d5-b9f0-94440a2c3506'::uuid, '1200510', 5), ('d57cceb6-0823-5a94-9049-4c55aba44d69'::uuid, '1200300', 5), ('ccba59b0-fb43-5590-8fc1-6ddccbcbf46b'::uuid, '4825170', 7), ('9f375c49-04b0-528f-8a5a-e9496b80e8b8'::uuid, '4825260', 7), ('57f62331-7bd1-5f6a-8c5d-e5c965cbc05a'::uuid, '2400570', 5), ('2ea18e2d-1d8d-5853-9e46-9c910c9708f4'::uuid, '5102250', 9), ('dd3c4dfe-9042-526f-b920-35feb312844d'::uuid, '5103840', 11), ('b93d7425-b909-5bda-b548-cdd4ae1942c4'::uuid, '2706090', 6), ('dd9a892f-b1b9-5ad4-8643-7d380e567220'::uuid, '0608460', 5)) v(did, geo, seats)
      JOIN essentials.geofence_boundaries g ON g.geo_id = v.geo AND g.mtfcc = 'G5420') s
   WHERE s.want = s.got;
  IF n <> 9 THEN RAISE EXCEPTION 'address round trip: only % of 9 boards resolve all their holders', n; END IF;

  RAISE NOTICE 'CA_0308 OK: 9 boards, 60 seats (59 held, 1 vacant), 84 people, 52 record voters seated on their record dates';
END $$;

COMMIT;
